def semver_sort(versions):
    def parse(v):
        core = v.split('+', 1)[0]
        if '-' in core:
            main, pre = core.split('-', 1)
        else:
            main, pre = core, None
        major, minor, patch = (int(x) for x in main.split('.'))
        pre_ids = pre.split('.') if pre is not None else None
        return (major, minor, patch, pre_ids)

    def pre_key(pre_ids):
        if pre_ids is None:
            return (1,)
        key = []
        for ident in pre_ids:
            if ident.isdigit():
                key.append((0, int(ident), ''))
            else:
                key.append((1, 0, ident))
        return (0, len(pre_ids), key)

    def full_key(v):
        major, minor, patch, pre_ids = parse(v)
        return (major, minor, patch, pre_key(pre_ids))

    return sorted(versions, key=full_key)

